  $('result-symbol').textContent=result.correct?'✓':'↺';$('result-symbol').classList.toggle('incorrect',!result.correct);
  $('result-title').textContent=result.correct?'Il conto torna.':'Ritroviamo il filo.';
  $('result-copy').textContent=mode==='grow' && !answerIsFinal?(result.correct?(result.speed===session.speed?'Ritmo massimo raggiunto: 0,4 s per carta.':`Il ritmo cresce: da ${number(result.speed,1)} a ${number(session.speed,1)} s per carta.`):`Scarto di ${Math.abs(result.answer-result.actual)}. Il ritmo resta a ${number(session.speed,1)} s per carta.`):result.correct?'Precisione e concentrazione. Continua così.':`Scarto di ${Math.abs(result.answer-result.actual)}. Rivedi le carte e riparti con calma.`;
  const both=result.countType==='both';$('your-count').textContent=both?`RC ${signed(result.answer)}`:signed(result.answer);$('correct-count').textContent=both?`RC ${signed(result.actual)}`:signed(result.actual);$('your-true-count').hidden=!both;$('correct-true-count').hidden=!both;$('your-true-count').textContent=both?`TC ${signed(result.trueAnswer)}`:'';$('correct-true-count').textContent=both?`TC ${signed(result.trueActual)}`:'';if(both)$('result-copy').textContent=`Running count: ${result.runningCorrect?'corretto':'da correggere'}. True count: ${result.trueCorrect?'corretto':'da correggere'}.${mode==='grow'&&!answerIsFinal?` Ritmo: ${number(session.speed,1)} s / carta.`:''}`;
  $('result-meta').textContent=`${session.index} carte · ${formatTime(getElapsed())} di attività${session.assisted?' · Sessione con conteggio visibile: esclusa dalla precisione.':''} · ${COUNTING_METHODS[session.countingMethod].name}${result.countType!=='running'?` · RC ${signed(session.count)} ÷ ${number(remainingDecks(),2)} mazzi = ${number(both?result.rawTrueActual:result.rawActual,3)} → ${signed(both?result.trueActual:result.actual)}`:''}`;
  let running=session.countStart||0;const cards=mode==='realistic'?session.visibleCards:session.shoe.slice(0,session.index);const start=Math.max(checkpointStart,cards.length-52);
  const review=cards.map((card,i)=>{running+=card.value;return i<start?'':`<div class="review-card ${['♥','♦'].includes(card.suit)?'red':''}" aria-label="Carta ${i+1}, ${card.rank} ${card.suit}, valore ${signed(card.value)}, conto ${signed(running)}">${card.rank}${card.suit}<small>${i+1} · ${signed(card.value)}</small><b>${signed(running)}</b></div>`;}).join('');
  $('card-review').innerHTML=review;
  $('review-details').querySelector('summary').textContent=start>0?`Rivedi le carte ${start+1}–${session.index}`:'Rivedi le carte e il conteggio';
  checkpointStart=session.index;
  $('continue-button').innerHTML=`${answerIsFinal?'Torna al tavolo':'Continua la sessione'}${icon('arrow')}`;
  if(answerIsFinal)saveSession();celebrateAnswer(result.correct);renderControls();$('continue-button').focus();
