function saveSession(){if(session.saved)return;session.saved=true;const completedAt=new Date();const record={id:`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,12)}`,date:completedAt.toISOString(),mode,decks:session.decks,speed:mode==='grow'?2:settings.speed,peakSpeed:session.peakSpeed,growths:session.growths,manual:isManual(),countType:session.countType||'running',countingMethod:session.countingMethod,rounds:session.round||0,cards:session.index,duration:Math.round(getElapsed()),assisted:session.assisted,checks:session.checks.map(c=>({...c})),finalCorrect:lastResult.correct};
  session.reward=applyCompletion(progress,record,profile.seed,completedAt);record.xp=session.reward.baseXP;history.unshift(record);history=trimHistory(history);persist();renderStats();renderGamification();
  const reward=session.reward;$('reward-result').dataset.levelUp=String(reward.levelUp);$('reward-result').hidden=false;$('reward-result').innerHTML=`<div>${icon(reward.levelUp?'trophy':'bolt')}<strong>${reward.totalXP?'+'+reward.totalXP+' XP':'Sessione conclusa'}</strong>${reward.levelUp?`<span>Livello ${reward.level}!</span>`:''}</div><p>${session.assisted?(reward.baseXP?'Sessione assistita: 3 XP. Le missioni non avanzano.':'Sessione assistita: servono tutte le risposte corrette per ottenere 3 XP.'):(reward.baseXP?(mode==='grow'?`${reward.baseXP} XP · ${session.checks.filter(c=>c.correct).length}/${session.checks.length} verifiche corrette. 20% completamento + 80% precisione.`:`${reward.baseXP} XP per la sessione perfetta.`):'Per gli XP di sessione servono tutte le risposte corrette, senza aiuti.')}${reward.missionXP?` +${reward.missionXP} XP dalle missioni completate.`:''}</p>`;
}
function continueSession(){$('answer-dialog').close();if(answerIsFinal){phase='complete';setStatus('Sessione completata');$('stage-message').innerHTML='<h2>Ben giocato</h2>';applySettings();if(session.reward?.levelUp)toast(`Nuovo livello: ${session.reward.level}. Continua così!`);}else{phase='paused';setStatus('In pausa');if(mode==='realistic'){beginTableRound(session);renderTable();}else if(session.index)renderCard(session.shoe[session.index-1]);renderControls();renderCounts();toast('Premi Riprendi quando sei pronto.');}}
function showHelp(){showView('manual');}
function showView(name){const views=['dashboard','training','stats','missions','account','streak','manual'];if(!views.includes(name))return;if(name!=='training')pause();activeView=name;for(const view of views)$(view+'-view').hidden=name!==view;for(const [view,id] of Object.entries({dashboard:'nav-dashboard',training:'nav-training',stats:'nav-stats',manual:'nav-help'})){$(id).classList.toggle('active',name===view);$(id).removeAttribute('aria-current');if(name===view)$(id).setAttribute('aria-current','page');}for(const [view,id] of Object.entries({account:'header-account',streak:'header-streak-button'}))$(id).setAttribute('aria-pressed',String(name===view));$('breadcrumb').textContent=({dashboard:'Dashboard',training:'Allenamento',stats:'Statistiche',missions:'Missioni',account:'Account',streak:'Streak',manual:'Manuale'})[name];refreshCalendar();if(name==='stats')renderStats();if(['dashboard','missions','account','streak'].includes(name))renderGamification();window.scrollTo({top:0,behavior:'auto'});scheduleTableFit();revealVisual($(name+'-view'));}
function renderDashboard(info=levelInfo(progress.xp),streak=streakInfo(progress)){
 const stats=summarize(history),last=latestSession(history);$('dashboard-today').textContent=new Date().toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'});$('dashboard-greeting').textContent=`Ciao, ${profile.name}.`;$('dashboard-level').textContent=info.level;$('dashboard-rank').textContent=info.rank;$('dashboard-level-copy').textContent=`Mancano ${number(info.remaining)} XP al prossimo livello.`;$('dashboard-xp').textContent=`${number(info.current)} / ${number(info.needed)} XP`;$('dashboard-next').textContent=`Livello ${info.level+1}`;$('dashboard-xp-fill').style.width=info.percent+'%';$('dashboard-xp-bar').setAttribute('aria-valuenow',String(Math.round(info.percent)));$('dashboard-xp-bar').setAttribute('aria-valuetext',`${info.current} di ${info.needed} XP`);$('dashboard-total').textContent=`${number(progress.xp)} XP totali · ${number(progress.totalCompleted)} ${progress.totalCompleted===1?'sessione completata':'sessioni completate'}`;$('dashboard-streak').textContent=streak.current;$('dashboard-streak-note').textContent=streak.todayDone?'Oggi hai già fatto la tua parte':streak.current?'Allenati oggi per continuare':'Completa una sessione al giorno per iniziare una serie.';$('dashboard-accuracy').textContent=stats.accuracy===null?'—':stats.accuracy+'%';$('dashboard-accuracy-note').textContent=stats.checks?`${stats.correct} / ${stats.checks} verifiche senza aiuti`:'Ancora nessuna verifica senza aiuti';
 $('dashboard-last-date').textContent=last?new Date(last.date).toLocaleDateString('it-IT',{day:'numeric',month:'short'}):'';const accuracy=last?sessionAccuracy(last):null;$('dashboard-last-content').innerHTML=last?`<div class="last-mode">${icon(MODE_INFO[last.mode].icon)}<div><h3>${MODE_INFO[last.mode].name}</h3><span>${HISTORICAL_METHOD_NAMES[historyMethod(last.countingMethod)]} · ${last.countType==='both'?'RC + TC':last.countType==='true'?'True count':'Running count'}</span></div></div><div class="last-session-values"><div><strong>${last.cards}</strong><span>Carte osservate</span></div><div><strong>${accuracy===null?'—':accuracy+'%'}</strong><span>Precisione senza aiuti</span></div><div><strong>${formatTime(last.duration)}</strong><span>Tempo attivo</span></div></div>`:'<div class="dashboard-empty"><span>♠</span><h3>Il tuo primo allenamento ti aspetta.</h3><p>Scegli una modalità e comincia dal tuo ritmo.</p></div>';
 $('dashboard-challenge-list').innerHTML=progress.daily.missions.map(m=>{const value=Math.min(m.target,missionValue(m,progress.daily.metrics));return `<article class="overview-goal ${m.claimed?'done':''}"><div class="overview-goal-top"><span class="overview-goal-icon">${icon(m.claimed?'check':m.icon)}</span><small>+${m.xp} XP</small></div><strong>${escapeHtml(m.title)}</strong><p>${escapeHtml(m.description)}</p><div class="overview-goal-footer"><div class="overview-goal-track" role="progressbar" aria-label="${escapeHtml(m.title)}" aria-valuemin="0" aria-valuemax="${m.target}" aria-valuenow="${value}"><i style="width:${value/m.target*100}%"></i></div><span>${m.claimed?'Completata':value+' / '+m.target}</span></div></article>`;}).join('');
}
function renderStatsInsights(rows,pool){const points=recentAccuracy(rows);$('stats-accuracy-chart').innerHTML=points.length?points.map((p,i)=>`<button class="accuracy-column" data-point="${i}" aria-label="${MODE_INFO[p.mode].name}, ${new Date(p.date).toLocaleDateString('it-IT')}, precisione ${p.accuracy}%"><span class="accuracy-value">${p.accuracy}%</span><span class="accuracy-bar-track"><i style="height:${p.accuracy}%"></i></span><span>${new Date(p.date).toLocaleDateString('it-IT',{day:'numeric',month:'short'})}</span></button>`).join(''):'<div class="insight-empty">La tua prima verifica senza aiuti accenderà questo grafico.</div>';
 const last=points.at(-1);$('stats-chart-detail').textContent=last?`${MODE_INFO[last.mode].name} · ${last.cards} carte · ${last.accuracy}% · precisione calcolata sulle singole verifiche`:'Le sessioni con aiuti non entrano nel calcolo della precisione.';const days=activityDays(rows),max=Math.max(1,...days.map(d=>d.cards));$('stats-activity').innerHTML=days.map(d=>`<div class="activity-day ${d.sessions?'has-activity':''}" style="--activity:${d.cards/max}" title="${d.label}: ${d.sessions} sessioni, ${d.cards} carte" aria-label="${d.label}: ${d.sessions} sessioni, ${d.cards} carte"><i></i><span>${d.label.split(' ')[0]}</span></div>`).join('');$('stats-activity-note').textContent=`${days.filter(d=>d.sessions).length} giorni attivi su 14 · filtri correnti applicati`;
 $('stats-mode-comparison').innerHTML=MODE_ORDER.map(m=>{const list=filterSessions(pool,m),a=summarize(list);return `<div class="mode-comparison-row"><span class="comparison-icon">${icon(MODE_INFO[m].icon)}</span><div><strong>${MODE_INFO[m].name}</strong><span>${a.sessions} sessioni · ${number(a.cards)} carte</span></div><div class="comparison-track"><i style="width:${a.accuracy??0}%"></i></div><strong>${a.accuracy===null?'—':a.accuracy+'%'}</strong></div>`;}).join('');
}
function renderStats(){const pool=selectInsights(history,{days:statsDays,method:statsMethod}),rows=filterSessions(pool,statsMode);$('stats-period').value=String(statsDays);$('stats-method').value=statsMethod;$('stats-filter-note').textContent=statsDays?`Ultimi ${statsDays} giorni, incluso oggi`:'Tutto lo storico conservato sul dispositivo';const stats=summarize(rows);const label=statsMode==='all'?'Tutte le modalità':MODE_INFO[statsMode].name;
  for(const m of ['all',...MODE_ORDER]){$('stats-'+m).classList.toggle('selected',m===statsMode);$('stats-'+m).setAttribute('aria-selected',String(m===statsMode));$('stats-'+m+'-count').textContent=filterSessions(pool,m).length;}
  $('stats-content').setAttribute('aria-labelledby','stats-'+statsMode);$('stats-context-icon').innerHTML=icon(statsMode==='all'?'grid':MODE_INFO[statsMode].icon);$('stats-context-title').textContent=label;
  $('stats-context-copy').textContent=statsMode==='all'?'Training, Sprint, Grow e Realistic: tutti i progressi insieme.':statsMode==='training'?'Sessioni personalizzate, precisione e costanza.':statsMode==='sprint'?'Sfide da 5 a 30 carte. RC, TC o entrambi senza aiuti.':statsMode==='realistic'?'Un tavolo di blackjack, tutte le carte scoperte e il conteggio scelto a ogni mano.':'Tre mazzi, 117 carte e 9 verifiche: il ritmo cresce fino al 75% del sabot.';
  const boxes=[['Sessioni completate',number(stats.sessions),statsMode==='all'?'200 Training · 100 per le altre modalità':statsMode==='training'?'ultime 200 sessioni Training':'ultime 100 di questa modalità'],['Precisione senza aiuti',stats.accuracy===null?'—':`${stats.accuracy}%`,`${stats.correct} corrette su ${stats.checks} verifiche`],['Carte osservate',number(stats.cards),'delle sessioni completate'],['Tempo attivo',formatTime(rows.reduce((total,s)=>total+s.duration,0)),`${stats.best} verifiche corrette consecutive · miglior serie`]];
  renderStatsInsights(rows,pool);$('stats-summary').innerHTML=boxes.map(([label,value,note])=>`<div class="stat-box"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('');
  $('grow-record').hidden=statsMode!=='grow';const fastest=rows.length?Math.min(...rows.map(s=>Number.isFinite(s.peakSpeed)?s.peakSpeed:s.speed)):null;
  $('grow-record').innerHTML=`<div>${icon('grow')}<div><span>Il tuo ritmo migliore</span><strong>${fastest===null?'—':number(fastest,1)+' s / carta'}</strong></div></div><p>${fastest===null?'Completa una sessione Grow per stabilire il tuo primo record.':'Velocità effettivamente usata nelle tue sessioni Grow completate.'}</p>`;
  $('history-title').textContent=statsMode==='all'?'Tutte le sessioni':`Le tue sessioni ${MODE_INFO[statsMode].name}`;$('history-description').textContent=statsMode==='all'?'Sessioni dalla più recente.':statsMode==='training'?'Le ultime 200 sessioni Training.':'Le ultime 100 di questa modalità.';
  $('history-empty').hidden=rows.length>0;$('history-body').parentElement.hidden=rows.length===0;$('clear-history').disabled=rows.length===0;$('clear-history').textContent=statsMode==='all'?'Cancella tutti i dati':'Cancella questa modalità';
  $('empty-title').textContent=statsMode==='all'?'La prima carta è tutta da giocare.':`Il tuo percorso ${MODE_INFO[statsMode].name} inizia qui.`;$('empty-copy').textContent=statsMode==='all'?'Completa una sessione e ritroverai qui i tuoi progressi.':'Completa una sessione in questa modalità per vedere le sue statistiche.';
  const pages=Math.max(1,Math.ceil(rows.length/5));historyPage=Math.min(historyPage,pages-1);$('history-pagination').hidden=rows.length<=5;$('history-page-label').textContent=`${historyPage+1} / ${pages}`;$('history-prev').disabled=historyPage===0;$('history-next').disabled=historyPage>=pages-1;$('history-description').textContent=rows.length?`${historyPage*5+1}–${Math.min(rows.length,historyPage*5+5)} di ${rows.length} sessioni · 5 per pagina`:'Le sessioni appariranno qui, 5 per pagina.';
  $('history-body').innerHTML=rows.slice(historyPage*5,historyPage*5+5).map(s=>{const date=new Date(s.date);const checks=s.checks.filter(c=>!c.assisted);const pace=s.mode==='grow'?`2,0 → ${number(Number.isFinite(s.peakSpeed)?s.peakSpeed:2,1)} s`:s.manual?'Manuale':`${number(s.speed,2)} s`;return `<tr><td>${date.toLocaleDateString('it-IT',{day:'2-digit',month:'short'})}<small>${date.toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})} · ${date.getFullYear()}</small></td><td><span class="history-mode">${icon(MODE_INFO[s.mode].icon)}${MODE_INFO[s.mode].name}</span><small>${s.decks} ${s.decks===1?'mazzo':'mazzi'} · ${HISTORICAL_METHOD_NAMES[historyMethod(s.countingMethod)]}${s.countType==='both'?' · RC + TC':s.countType==='true'?' · True count':''}${s.mode==='realistic'?` · ${s.rounds||0} mani`:''}${s.assisted?' · con aiuti':''}</small></td><td>${s.cards}<small>${formatTime(s.duration)}</small></td><td>${pace}</td><td>${checks.length?`${checks.filter(c=>c.correct).length}/${checks.length}`:'Con aiuti'}</td><td><span class="outcome ${s.finalCorrect?'':'wrong'}">${s.finalCorrect?'Corretto':'Da riprovare'}</span></td></tr>`;}).join('');
}

function updateConfig(key,value){if(['running','paused','answering','feedback'].includes(phase))return;settings[key]=value;persist();if(phase==='complete'){reset();}else applySettings();}
const escapeHtml=text=>String(text).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function renderAvatar(id){const el=$(id);if(profile.avatar)el.innerHTML=`<img src="${profile.avatar}" alt="">`;else el.textContent=profile.name.trim().split(/\s+/).slice(0,2).map(word=>[...word][0]||'').join('').toUpperCase();}
function renderGamification(){const info=levelInfo(progress.xp),streak=streakInfo(progress);$('header-streak').textContent=streak.current;$('header-level').textContent='Livello '+info.level;$('header-xp-fill').style.width=info.percent+'%';$('header-xp-bar').setAttribute('aria-valuenow',String(Math.round(info.percent)));$('header-xp-bar').setAttribute('aria-valuetext',`${info.current} di ${info.needed} XP verso il livello ${info.level+1}`);renderAvatar('header-avatar');renderAvatar('dashboard-avatar');$('dashboard-mission-count').textContent=progress.daily.missions.filter(m=>m.claimed).length+'/3';$('header-streak-button').setAttribute('aria-label',`Streak: ${streak.current} giorni. Apri i dettagli`);$('header-account').setAttribute('aria-label',`Apri Account di ${profile.name}, livello ${info.level}`);$('dashboard-profile').setAttribute('aria-label',`Apri Account di ${profile.name}: profilo, immagine e dati`);renderAccount(info);renderStreak(streak);renderMissions();renderDashboard(info,streak);}
function renderAccount(info=levelInfo(progress.xp)){
 renderAvatar('profile-avatar');$('profile-name').textContent=profile.name;$('profile-rank').textContent=info.rank;if(document.activeElement!==$('profile-name-input'))$('profile-name-input').value=profile.name;$('avatar-remove').disabled=!profile.avatar;
 $('account-level').textContent=info.level;$('account-rank').textContent=info.rank;$('account-level-xp').textContent=`${number(info.current)} / ${number(info.needed)} XP`;$('account-next-level').textContent='Livello '+(info.level+1);$('account-xp-fill').style.width=info.percent+'%';$('account-xp-bar').setAttribute('aria-valuenow',String(Math.round(info.percent)));$('account-xp-remaining').textContent=`Mancano ${number(info.remaining)} XP al prossimo livello.`;$('account-total-xp').textContent=number(progress.xp);$('account-successes').textContent=number(progress.totalSuccess);$('account-completed').textContent=number(progress.totalCompleted);
}
function renderStreak(streak=streakInfo(progress)){
 $('streak-count').textContent=streak.current;$('streak-unit').textContent=streak.current===1?'giorno di streak':'giorni di streak';$('streak-best').textContent=streak.best;$('streak-copy').textContent=streak.todayDone?'Giornata completata. Ci vediamo domani.':streak.current?'Mantieni il ritmo: completa una modalità oggi.':'Completa una modalità oggi per iniziare.';
 const now=new Date(),days=new Set(progress.activityDays),today=dayKey(now);const week=[];for(let i=6;i>=0;i--){const date=new Date(now.getFullYear(),now.getMonth(),now.getDate()-i,12),key=dayKey(date),done=days.has(key);week.push(`<div class="streak-day ${done?'done':''} ${key===today?'is-today':''}" aria-label="${date.toLocaleDateString('it-IT')}: ${done?'completato':'non completato'}"><span>${date.toLocaleDateString('it-IT',{weekday:'short'}).replace('.','')}</span><strong>${done?icon('check'):date.getDate()}</strong><small>${key===today?'oggi':''}</small></div>`);}$('streak-week').innerHTML=week.join('');
}
function renderMissions(){
 const daily=progress.daily,done=daily.missions.filter(m=>m.claimed).length;$('mission-date').textContent=new Date().toLocaleDateString('it-IT',{day:'numeric',month:'long'});$('missions-done').textContent=`${done} di 3 completate`;$('mission-rewards-total').textContent=`Ottenuti ${daily.missions.filter(m=>m.claimed).reduce((sum,m)=>sum+m.xp,0)} / ${daily.missions.reduce((sum,m)=>sum+m.xp,0)} XP bonus`;$('missions-reset').textContent='Si rinnovano a mezzanotte, secondo l’orario del tuo dispositivo.';
 $('mission-grid').innerHTML=daily.missions.map((mission,i)=>{const value=Math.min(mission.target,missionValue(mission,daily.metrics));return `<article class="mission-card ${mission.claimed?'completed':''}"><div class="mission-card-top"><span class="mission-icon">${icon(mission.claimed?'check':mission.icon)}</span><span class="mission-xp">+${mission.xp} XP</span></div><span class="mission-overline">${['RISCALDAMENTO','CONCENTRAZIONE','UN PASSO IN PIÙ'][i]}</span><h2>${escapeHtml(mission.title)}</h2><p>${escapeHtml(mission.description)}</p><div class="mission-progress-caption"><span>${mission.claimed?'Completata · XP assegnati':value+' / '+mission.target}</span><span>${Math.round(value/mission.target*100)}%</span></div><div class="mission-progress" role="progressbar" aria-label="${escapeHtml(mission.title)}" aria-valuemin="0" aria-valuemax="${mission.target}" aria-valuenow="${value}"><div style="width:${value/mission.target*100}%"></div></div></article>`;}).join('');

}
function refreshCalendar(){if(refreshDay(progress,profile.seed)){persist();renderGamification();}else if(['dashboard','account','missions','streak'].includes(activeView))renderGamification();scheduleCalendar();}
function scheduleCalendar(){clearTimeout(calendarTimer);calendarTimer=setTimeout(()=>{refreshCalendar();renderGamification();},nextMidnightDelay());}
function saveProfile(event){event.preventDefault();const name=$('profile-name-input').value.trim().replace(/\s+/g,' ').slice(0,24);if(!name){$('profile-status').textContent='Inserisci un nome prima di salvare.';return;}const previous=profile.name;profile.name=name;if(persist()){$('profile-status').textContent='Nome aggiornato.';toast('Il tuo profilo è aggiornato.');}else{profile.name=previous;$('profile-status').textContent='Il browser non ha potuto salvare il nome.';}renderGamification();}
async function saveAvatar(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Scegli un’immagine JPG, PNG o WebP.');return;}if(file.size>10*1024*1024){toast('Scegli un’immagine più piccola di 10 MB.');return;}
 let url;try{url=URL.createObjectURL(file);const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});if(!image.naturalWidth||!image.naturalHeight||image.naturalWidth*image.naturalHeight>80000000)throw Error('image-size');const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const size=Math.min(image.naturalWidth,image.naturalHeight);canvas.getContext('2d').drawImage(image,(image.naturalWidth-size)/2,(image.naturalHeight-size)/2,size,size,0,0,256,256);const avatar=canvas.toDataURL('image/webp',.86);if(avatar.length>300000)throw Error('image-size');const previous=profile.avatar;profile.avatar=avatar;if(!persist()){profile.avatar=previous;toast('Immagine non salvata: spazio del browser insufficiente.');}else{$('profile-status').textContent='Immagine aggiornata.';toast('Nuova immagine del profilo.');}renderGamification();}catch{toast('Impossibile aprire l’immagine. Prova un altro file JPG, PNG o WebP.');}finally{if(url)URL.revokeObjectURL(url);$('avatar-input').value='';}}
function exportAccount(){const blob=new Blob([JSON.stringify({app:'MyCounting',version:11,kind:'account-backup',exportedAt:new Date().toISOString(),settings,history,profile,progress},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`MyCounting-account-${dayKey()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function applyImportedAccount(candidate,resetting=false){
 try{localStorage.setItem(KEY,JSON.stringify(candidate));}catch{toast((resetting?'Ripristino non salvato.':'Importazione non salvata.')+' Libera spazio nel browser e riprova. I dati attuali non sono stati cambiati.');return false;}
 stopTimers();settings=candidate.settings;history=candidate.history;profile=candidate.profile;progress=candidate.progress;storageAvailable=true;statsMode='all';statsDays=0;statsMethod='all';historyPage=0;mode='training';reset();renderStats();renderGamification();showView('account');$('profile-status').textContent=resetting?'Account ripristinato. Riparti dal livello 1.':'Account importato correttamente.';toast(resetting?'Account ripristinato. Un nuovo inizio.':'Account e progressi importati.');return true;
}
let importReading=false;
async function importAccount(file){if(!file)return;if(importReading){toast('Attendi la lettura del file in corso.');return;}if(file.size>5*1024*1024){toast('Il file supera 5 MB. Scegli un’esportazione account MyCounting.');$('account-import-input').value='';return;}
 importReading=true;try{const text=await file.text();let data;try{data=JSON.parse(text);}catch{throw Error('Il file non contiene un JSON valido.');}const candidate=prepareAccountImport(data);const level=levelInfo(candidate.progress.xp).level;
 confirm(`Importare l’account di ${candidate.profile.name}?`,`Livello ${level} · ${number(candidate.progress.xp)} XP · ${candidate.history.length} sessioni salvate. Questo file sostituirà il profilo, lo storico e i progressi attuali${session&&['running','paused'].includes(phase)?' e interromperà la sessione in corso':''}.`,()=>applyImportedAccount(candidate));
 }catch(error){toast(error.message || 'Non è stato possibile importare questo file.');}finally{importReading=false;$('account-import-input').value='';}
}
function renderModeReward(){const guided=isCountDrill()&&(session&&['running','paused','answering','feedback'].includes(phase)?session.assisted:settings.showCount);const reward=sessionXP({mode,cards:mode==='sprint'?settings.sprintLength:currentDecks()*52*(mode==='grow'||usesTrueCount()?.75:1),decks:currentDecks(),countType:currentCountType(),assisted:guided,finalCorrect:true,checks:[{correct:true,assisted:guided}]});$('mode-xp').innerHTML=icon('trophy')+`<span>${mode==='realistic'?'25 XP per mano · massimo 125 XP senza errori':mode==='grow'?`Fino a ${reward} XP · anche con errori`:guided?'Con aiuti: massimo 3 XP · missioni in pausa':reward+' XP senza errori e senza aiuti'}</span>`;}
const tableMotionSnapshots=new Map();
function tableCardMarkup(card,arrival=''){const motionClass=arrival?' '+arrival:'';const motionStyle=arrival?` style="animation-duration:${Math.min(180,currentSpeed()*1000*.28)}ms"`:'';if(card.hidden)return `<span class="table-card table-card-back${motionClass}"${motionStyle} aria-label="Carta coperta"><img src="./assets/mark-transparent.webp" alt=""></span>`;return `<span class="table-card ${['♥','♦'].includes(card.suit)?'red':''}${motionClass}"${motionStyle} aria-label="${card.rank} ${card.suit}"><b>${card.rank}</b><span>${card.suit}</span></span>`;}
function renderTableHand(id,cards,live){$(id).style.setProperty?.('--cards',String(Math.max(1,cards.length)));const previous=tableMotionSnapshots.get(id),signature=cards.map(c=>`${c.id}:${c.hidden}`).join('|');if(previous?.session===live&&previous.signature===signature)return;const markup=cards.map(card=>{const old=previous?.session===live?previous.cards.get(card.id):undefined;return tableCardMarkup(card,old===undefined?'is-arriving':old&&!card.hidden?'is-revealing':'');}).join('');$(id).innerHTML=markup;tableMotionSnapshots.set(id,{session:live,signature,cards:new Map(cards.map(card=>[card.id,card.hidden]))});}
function tableTotal(cards){if(!cards.length)return '—';const visible=cards.filter(c=>!c.hidden),value=handValue(visible);if(cards.some(c=>c.hidden))return visible.length?`${value.total} + ?`:'?';return value.blackjack?'Blackjack':value.bust?`${value.total} · Sballato`:value.soft?`${value.total-10} / ${value.total}`:String(value.total);}
function renderTable(){const live=mode==='realistic'&&session?.mode==='realistic'?session:null,dealer=live?.dealer||[];$('stage-message').hidden=Boolean(live);$('table-stage').dataset.tableState=live?.stage||'idle';renderTableHand('dealer-cards',dealer,live);$('dealer-total').textContent=tableTotal(dealer);$('dealer-total').setAttribute('aria-label',dealer.some(c=>c.hidden)?'Totale scoperto del banco, più una carta coperta':'Totale del banco: '+tableTotal(dealer));for(let i=0;i<3;i++){const cards=live?.hands[i]||[];renderTableHand('seat-cards-'+i,cards,live);$('seat-total-'+i).textContent=live?.outcomes[i]||tableTotal(cards);$('table-seat-'+i).classList.toggle('active-seat',Boolean(live?.stage==='player'&&i===1));$('table-seat-'+i).dataset.outcome=live?.outcomes[i]||'';}$('table-round-label').textContent=live?`Mano ${live.round} / ${live.maxRounds}`:'Fino a 5 mani';const message=!live?'Prendi posto':live.stage==='player'?'Tocca a te · Carta o Sto':live.stage==='roundEnd'?`${live.outcomes[1]} · Verifica il conto quando sei pronto`:live.stage==='reveal'||live.stage==='dealer'?'Gioca il banco':live.stage==='players'?'Giocano gli altri posti':'Distribuzione in corso';$('table-message').textContent=message;$('table-turn-label').textContent=message;$('table-turn-label').hidden=!live;$('table-shoe-fill').style.height=live?`${(1-live.dealt/live.shoe.length)*100}%`:'100%';}
function playTable(action){if(mode!=='realistic'||phase!=='running')return;const event=tableAction(session,action);if(!event)return;if(event.card)sound();renderTable();renderProgress();renderControls();schedule();}
