function requestAccountReset(){if(importReading){toast('Attendi la lettura del file in corso.');return;}pause();confirm('Ripristinare l’account?','Nome, foto, XP, livello, streak, missioni, storico e impostazioni verranno cancellati. Ripartirai da zero. L’azione non può essere annullata: esporta prima i dati se vuoi conservarli.',()=>{const freshProfile=normalizeProfile({});applyImportedAccount({schema:11,settings:{...defaults},history:[],profile:freshProfile,progress:newProgress(freshProfile.seed)},true);});}
const MODE_GUIDES={
 training:[['Il metodo e il conto che vuoi allenare','Scegli Running count, True count oppure Entrambi (due risposte per verifica) con Hi-Lo, Zen e Wong Halves. Scegli il metodo sopra le impostazioni, poi da 1 a 8 mazzi e la velocità. Puoi avanzare a mano e verificare ogni 10, 20 o 52 carte, solo alla fine oppure a richiesta.'],['Running count e true count','Il running count è il totale cumulativo del metodo scelto dall’inizio del sabot. Il true count divide quel totale per i mazzi rimasti esatti e si tronca verso zero: +2,8 → +2; −2,8 → −2. Con true count o Entrambi la sessione termina al 75% del sabot (39 carte per mazzo iniziale) e il feedback mostra il calcolo.'],['Aiuti e XP','Senza aiuti e con tutte le verifiche corrette: 70 XP per mazzo in running count, oppure il 75% del premio arrotondato all’intero più vicino in true count o Entrambi (53–420 XP). Mostra conteggio rende assistita l’intera sessione anche se poi lo nascondi: massimo 3 XP e missioni in pausa.']],
 sprint:[['Una sequenza, una risposta','Scegli da 5 a 30 carte, da 1 a 8 mazzi e il ritmo che preferisci. Puoi anche usare l’avanzamento manuale.'],['Il conto resta nascosto','Scegli running count, true count o Entrambi e rispondi solo alla fine della sequenza. Il TC si tronca verso zero. Non ci sono verifiche intermedie né aiuti visibili.'],['Il premio','Una risposta corretta conclude la sfida con 13–30 XP in base alla lunghezza (20 XP con 15 carte). Le missioni pertinenti avanzano a sessione conclusa.']],
 grow:[['Il ritmo cresce','Parti con 3 mazzi e 2 secondi per carta. Scegli RC, TC o Entrambi; La distribuzione è automatica e il conteggio resta nascosto.'],['Una verifica ogni 13 carte','Inserisci il conteggio scelto, sempre cumulativo: non ricominciare da zero. Ogni risposta corretta accelera di 0,2 secondi per carta, fino a 0,4. Un errore mantiene la velocità raggiunta. Con RC, TC o Entrambi completi 117 carte e 9 verifiche: il 75% delle 156 carte iniziali. Restano 39 carte nel sabot (0,75 mazzi), così puoi calcolare anche il TC finale.'],['Una sessione completa','Dopo ogni feedback premi Continua e poi Riprendi. Grow assegna XP anche con errori: 20% per completare e 80% in proporzione alle verifiche corrette. Una sessione completa assegna da 50 a 248 XP con RC, TC o Entrambi. Una nuova sessione riparte sempre da 2 secondi per carta.']],
 realistic:[['Il tuo posto al tavolo','Un banco, due giocatori simulati e tu, senza puntate. Scegli da 1 a 8 mazzi e la velocità. Durante il tuo turno usa Carta o Sto; gli altri giocatori decidono in automatico in base alla propria mano e alla carta scoperta del banco.'],['Le regole del banco','Il banco sta su 17 anche soft (un Asso contato come 11). Se il banco ha blackjack naturale, lo rivela prima delle decisioni dei giocatori. Altrimenti la carta coperta resta nascosta fino al turno del banco. I totali morbidi mostrano entrambi i valori (es. 7 / 17). Non ci sono split o raddoppi. Il totale della mano usa le regole del blackjack; il conteggio segue il metodo selezionato, spiegato nel Manuale.'],['Conta solo ciò che vedi','Conta le carte scoperte di tutti i posti. La carta coperta del banco entra nel conto solo quando viene scoperta. Scegli nelle impostazioni running count, true count o Entrambi, se disponibili per il metodo scelto. Alla fine della mano puoi osservare gli esiti, poi premi Verifica conto e inserisci il conto scelto: il running count è cumulativo dall’inizio della sessione; il true count divide quel totale per i mazzi rimasti e si tronca verso zero (+2,8 → +2; −2,8 → −2). In true count resta sempre almeno una carta per mantenere definita la divisione; raggiunto quel limite la mano termina.'],['Durata e XP','Fino a 5 mani con lo stesso sabot, senza rimescolare. Se a fine mano rimangono meno di 20 carte, la sessione termina prima. Tutte le verifiche corrette danno 25 XP per mano completata, fino a 125 XP. Vincere o perdere la mano non cambia gli XP.']]
};
function showModeInfo(){pause();$('mode-info-title').textContent=MODE_INFO[mode].name;$('mode-info-content').innerHTML=[[methodInfo().name,settings.countingMethod==='halves'?'Parti da zero. RC con i tag originali a mezzi punti (es. +1,5); TC = RC ÷ mazzi rimasti, troncato a intero. Sono accettate virgola e punto nel RC.':'Parti da zero. RC è il totale cumulativo; TC è RC diviso per i mazzi rimasti. Entrambi richiede due numeri corretti nella stessa verifica.'],...MODE_GUIDES[mode]].map(([heading,copy])=>`<section><h3>${heading}</h3><p>${copy}</p></section>`).join('');$('mode-info-dialog').showModal();$('mode-info-close').focus();}
function fitTable(){const panel=$('training-panel');if(activeView!=='training'||!window.innerHeight||typeof panel.getBoundingClientRect!=='function')return;const viewport=window.visualViewport?.height||window.innerHeight,top=panel.getBoundingClientRect().top+(window.scrollY||0);const mobile=window.matchMedia?.('(max-width: 760px)')?.matches;const nav=$('primary-navigation');const reserved=mobile&&typeof nav.getBoundingClientRect==='function'?nav.getBoundingClientRect().height:0;const room=Math.floor(viewport-Math.max(0,top)-reserved-12);panel.style.height=Math.min(840,Math.max(150,room))+'px';$('session-configuration').style.height=mobile?'':panel.style.height;panel.classList.toggle('compact-table',room<390);scheduleSettingsHint();}
let tableFitFrame=null;
function scheduleTableFit(){if(typeof window.requestAnimationFrame!=='function')return;if(tableFitFrame!==null)window.cancelAnimationFrame?.(tableFitFrame);tableFitFrame=window.requestAnimationFrame(()=>{tableFitFrame=null;fitTable();});}
window.addEventListener('resize',scheduleTableFit);window.visualViewport?.addEventListener('resize',scheduleTableFit);
