function setManualTopic(topic){if(!MANUAL_TOPICS.includes(topic))return;manualTopic=topic;for(const t of MANUAL_TOPICS){const active=t===topic;$('manual-panel-'+t).hidden=!active;$('manual-topic-'+t).classList.toggle('selected',active);$('manual-topic-'+t).setAttribute('aria-selected',String(active));$('manual-topic-'+t).setAttribute('tabindex',active?'0':'-1');}revealVisual($('manual-panel-'+topic));}
MANUAL_TOPICS.forEach((t,i)=>{$('manual-topic-'+t).addEventListener('click',()=>setManualTopic(t));$('manual-topic-'+t).addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?MANUAL_TOPICS[0]:e.key==='End'?MANUAL_TOPICS.at(-1):MANUAL_TOPICS[(i+(['ArrowDown','ArrowRight'].includes(e.key)?1:MANUAL_TOPICS.length-1))%MANUAL_TOPICS.length];setManualTopic(next);$('manual-topic-'+next).focus();});});
