const manualSequence=['5','K','3','A','8','2'];
function renderManualDemo(){for(const method of Object.keys(COUNTING_METHODS))$('manual-method-'+method).hidden=method!==manualMethod;const start=initialCount(manualMethod,2),count=manualSequence.slice(0,manualDemoIndex).reduce((sum,rank)=>sum+valueOf(rank,manualMethod),start),current=manualSequence[manualDemoIndex-1];$('manual-demo-card').textContent=current||'?';$('manual-demo-count').textContent=signed(count);$('manual-demo-note').textContent=current?`Carta ${manualDemoIndex}: ${signed(valueOf(current,manualMethod))} al totale.`:'Si parte da zero.';$('manual-demo-history').innerHTML=manualSequence.map((rank,index)=>`<span class="${index<manualDemoIndex?'seen':''} ${index===manualDemoIndex-1?'current':''}">${rank}</span>`).join('');$('manual-demo-next').innerHTML=`${manualDemoIndex===manualSequence.length?'Ricomincia':manualDemoIndex?'Prossima carta':'Prima carta'}${icon(manualDemoIndex===manualSequence.length?'reset':'arrow')}`;}
