function renderStrategy(){const kind=Object.hasOwn(STRATEGY_ROWS,$('strategy-type').value)?$('strategy-type').value:'hard';$('strategy-table').innerHTML=`<table class="strategy-table"><caption>La tua mano a sinistra · carta scoperta del banco in alto</caption><thead><tr><th scope="col">Mano</th>${STRATEGY_COLUMNS.map(c=>`<th scope="col">${c}</th>`).join('')}</tr></thead><tbody>${STRATEGY_ROWS[kind].map(([label,actions])=>`<tr><th scope="row">${label}</th>${[...actions].map(a=>`<td class="strategy-${a}" title="${STRATEGY_ACTIONS[a]}">${a}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function renderDeviation(){const index=Number($('deviation-case').value)||0,raw=$('deviation-tc').value.trim(),tc=Number(raw),decision=raw!==''&&tc>=-10&&tc<=10?deviationDecision(index,tc):null;if(!decision){$('deviation-result').textContent='Inserisci un TC esatto tra −10 e +10.';return;}$('deviation-result').dataset.active=String(decision.active);$('deviation-result').innerHTML=`<span>${decision.entry.hand} contro ${decision.entry.dealer} · indice ${signed(decision.entry.index)}</span><strong>${decision.action}</strong><p>TC esatto ${signed(tc)} ${decision.active?'raggiunge':'non raggiunge'} la soglia. ${decision.entry.note}</p>`;}
