$('nav-training').addEventListener('click',()=>showView('training'));$('nav-stats').addEventListener('click',()=>showView('stats'));$('empty-start').addEventListener('click',()=>{if(statsMode!=='all')setMode(statsMode);showView('training');});
['all',...MODE_ORDER].forEach(m=>$('stats-'+m).addEventListener('click',()=>{statsMode=m;historyPage=0;renderStats();}));
MODE_ORDER.forEach((m,index)=>$('mode-'+m).addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?'training':e.key==='End'?MODE_ORDER.at(-1):MODE_ORDER[(index+(e.key==='ArrowRight'?1:MODE_ORDER.length-1))%MODE_ORDER.length];setMode(next);$('mode-'+next).focus();}));
$('answer-form').addEventListener('submit',submitAnswer);$('answer-cancel').addEventListener('click',cancelAnswer);$('continue-button').addEventListener('click',continueSession);
$('answer-dialog').addEventListener('cancel',e=>{e.preventDefault();if(phase==='feedback')continueSession();else if(!answerIsFinal && !['grow','realistic'].includes(mode))cancelAnswer();});
$('confirm-no').addEventListener('click',()=>{$('confirm-dialog').close();confirmAction=null;});$('confirm-yes').addEventListener('click',()=>{const action=confirmAction;confirmAction=null;$('confirm-dialog').close();action?.();});$('confirm-dialog').addEventListener('cancel',()=>confirmAction=null);
$('clear-history').addEventListener('click',()=>{const target=statsMode;confirm(target==='all'?'Cancellare tutto lo storico?':`Azzerare ${MODE_INFO[target].name}?`,target==='all'?'Verrà eliminato tutto lo storico, anche fuori dai filtri di periodo e metodo. XP, livello, streak e missioni restano invariati. Puoi esportare prima i dati.':`Verranno eliminate tutte le sessioni ${MODE_INFO[target].name}, anche fuori dai filtri di periodo e metodo. Le altre modalità mantengono lo storico.`,()=>{history=target==='all'?[]:history.filter(s=>s.mode!==target);persist();renderStats();toast('Statistiche azzerate. Un nuovo punto di partenza.');});});
const modals=['answer-dialog','confirm-dialog','mode-info-dialog'];
document.addEventListener('keydown',e=>{if(!$('boot-screen').hidden)return;if(modals.some(id=>$(id).open)||/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName)||$('training-view').hidden)return;if(e.key===' '){e.preventDefault();start();}else if(e.key==='ArrowRight'&&isManual()){e.preventDefault();step();}else if(e.key.toLowerCase()==='v'&&isCountDrill()&&['running','paused'].includes(phase))askAnswer(session.index===session.limit);});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshCalendar();if(document.hidden&&phase==='running'){pause('Pausa automatica');toast('Sessione in pausa: riprendi quando torni.');}});
window.addEventListener('pagehide',()=>{pause();persist();});
applySettings();renderStats();renderGamification();persist();scheduleCalendar();renderManualDemo();renderManualCalculator();setManualTopic('basics');prepareLessons();finishBoot();
if(!storageAvailable)setTimeout(()=>toast('Salvataggio locale non disponibile. Esporta i progressi per conservarli.'),1000);
if('serviceWorker' in navigator && ['https:','http:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{});
